// Line mode: a straight piece of route that ignores the map (the rider knows a way the map does not have). It is
// drawn every STEP_M with heights from the same elevation tiles the live builder reads (GSI dem_png z13 in Japan,
// AWS Terrain Tiles z13 elsewhere), and comes back in the shape of a route result (best-route.mjs) so it joins the
// other legs: coords, lengthM, profile, gain / loss, steepness segments. No elevation (no tile, sea, offline): the
// route has no heights (gainM null), like an old graph without elevation.
// Pure apart from the tile reader passed in; runs in Node (test/elev.mjs).
import { gradeBin, gainLoss, thin } from './best-route.mjs';

export const STEP_M = 30, DEM_Z = 13;
const KY = 110574, kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;
export const metres = (a, b) => Math.hypot((a[0] - b[0]) * kxAt((a[1] + b[1]) / 2), (a[1] - b[1]) * KY);

// points every stepM along a -> b, both ends included
export function densify(a, b, stepM = STEP_M) {
  const n = Math.max(1, Math.ceil(metres(a, b) / stepM)), out = [];
  for (let k = 0; k <= n; k++) out.push([a[0] + ((b[0] - a[0]) * k) / n, a[1] + ((b[1] - a[1]) * k) / n]);
  return out;
}

// web-mercator tile and pixel of a point at zoom z (256 px tiles)
function tilePixel([lon, lat], z) {
  const n = 2 ** z, x = ((lon + 180) / 360) * n, s = Math.sin((lat * Math.PI) / 180), y = (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * n;
  const tx = Math.floor(x), ty = Math.floor(y);
  return { tx, ty, px: Math.min(255, Math.floor((x - tx) * 256)), py: Math.min(255, Math.floor((y - ty) * 256)) };
}
// decode an elevation PNG's RGBA into metres (NaN = no data)
export function decodeDem(rgba, source) {
  const v = new Float32Array(65536);
  for (let i = 0; i < 65536; i++) {
    if (source === 'osm') { v[i] = rgba[4 * i] * 256 + rgba[4 * i + 1] + rgba[4 * i + 2] / 256 - 32768; continue; } // Terrarium
    const x = rgba[4 * i] * 65536 + rgba[4 * i + 1] * 256 + rgba[4 * i + 2];
    v[i] = x === 8388608 ? NaN : (x > 8388608 ? x - 16777216 : x) * 0.01;
  }
  return v;
}
export const demTileUrl = (source, z, x, y) => (source === 'osm' ? `https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${z}/${x}/${y}.png` : `https://cyberjapandata.gsi.go.jp/xyz/dem_png/${z}/${x}/${y}.png`);

// heights of points: getTile(z, x, y) resolves with a Float32Array(65536) of metres, or null (no tile). Gaps (NaN) take
// the nearest known height; all unknown: null.
export async function sampleElevation(pts, getTile, z = DEM_Z) {
  const tiles = new Map(), zs = [];
  for (const p of pts) {
    const { tx, ty, px, py } = tilePixel(p, z), key = `${tx}/${ty}`;
    if (!tiles.has(key)) tiles.set(key, getTile(z, tx, ty).catch(() => null));
    const t = await tiles.get(key);
    zs.push(t ? t[py * 256 + px] : NaN);
  }
  if (!zs.some(Number.isFinite)) return null;
  for (let k = 0; k < zs.length; k++) if (!Number.isFinite(zs[k])) { // nearest known height
    let d = 1; while (!Number.isFinite(zs[k - d]) && !Number.isFinite(zs[k + d])) d++;
    zs[k] = Number.isFinite(zs[k - d]) ? zs[k - d] : zs[k + d];
  }
  return zs;
}

// A route result for a straight line through pts ([lon, lat], already densified) with heights zs (or null).
export function lineRoute(pts, zs = null) {
  const cum = [0];
  for (let k = 1; k < pts.length; k++) cum.push(cum[k - 1] + metres(pts[k - 1], pts[k]));
  const L = cum[cum.length - 1], hasZ = !!zs && zs.length === pts.length;
  const profile = hasZ ? pts.map((_, k) => [cum[k], zs[k]]) : null;
  const features = [];
  let seg = null, steepM = 0;
  const flush = () => { if (seg && seg.coords.length > 1) features.push({ type: 'Feature', properties: { bin: seg.bin, grade_pct: +(100 * seg.gsum / (seg.len || 1)).toFixed(1), len_m: Math.round(seg.len), from_m: Math.round(seg.from), tunnel: 0 }, geometry: { type: 'LineString', coordinates: seg.coords } }); seg = null; };
  for (let k = 1; k < pts.length; k++) {
    const l = cum[k] - cum[k - 1], g = hasZ && l > 0 ? Math.abs(zs[k] - zs[k - 1]) / l : 0, b = gradeBin(g);
    if (g >= 0.08) steepM += l;
    if (!seg || seg.bin !== b) { flush(); seg = { bin: b, coords: [pts[k - 1]], len: 0, gsum: 0, from: cum[k - 1] }; }
    seg.coords.push(pts[k]); seg.len += l; seg.gsum += l * g;
  }
  flush();
  const gl = hasZ ? gainLoss(profile) : { gainM: null, lossM: null, gainRawM: null, lossRawM: null };
  return { line: true, coords: pts.map((p) => [p[0], p[1]]), chains: [], runs: [], lengthM: L, aboveM: 0, relaxed: false, turns: null,
    resistance: L, meanMultiplier: 1, steepM, tunnelM: 0, tunnelAvoidM: 0, unpavedM: 0, byClass: {}, shortestM: L, detourPct: 0,
    segments: { type: 'FeatureCollection', features }, ...gl, profile: hasZ ? thin(profile, 600) : null,
    minZ: hasZ ? Math.min(...zs) : null, maxZ: hasZ ? Math.max(...zs) : null, alternatives: [] };
}

// A tile reader for the browser: fetch (through the caller's cache), decode the PNG with createImageBitmap, keep the
// last tiles in memory. fetchBytes(url) resolves with bytes or null.
export function demReader(source, fetchBytes) {
  const memo = new Map();
  return (z, x, y) => {
    const url = demTileUrl(source, z, x, y);
    if (!memo.has(url)) {
      memo.set(url, (async () => {
        const bytes = await fetchBytes(url); if (!bytes) return null;
        const bmp = await createImageBitmap(new Blob([bytes], { type: 'image/png' }), { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
        const cv = new OffscreenCanvas(bmp.width, bmp.height), ctx = cv.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(bmp, 0, 0); bmp.close();
        return decodeDem(ctx.getImageData(0, 0, cv.width, cv.height).data, source);
      })());
      if (memo.size > 64) memo.delete(memo.keys().next().value);
    }
    return memo.get(url);
  };
}
