// Sign-in (optional): Firebase Auth with a Google account, project cyclescape-84f74 (plan §1b; CONTRACT §8).
// The Firebase JS SDK comes from Google's CDN as ES modules, loaded only when initAccount() is called (after the map
// has loaded), so the app starts without it and works without it. Nothing here runs at import time, so Node tests can
// import modules that import this one.
//   initAccount(config)  load the SDK, restore the session, finish a redirect sign-in; resolves once the user is known
//   onUser(fn)           fn({ uid, name, email, photo } | null) now and on every change; returns an unsubscribe function
//   signIn() / signOut() reject with a readable Error (err.code = Firebase's code) on failure
//   idToken()            the current ID token for the API, or null when signed out
const SDK = 'https://www.gstatic.com/firebasejs/12.16.0/';
let fb = null, auth = null, user = null, state = 'idle', initP = null, lastError = null;
const listeners = new Set();

const plain = (u) => (u ? { uid: u.uid, name: u.displayName ?? u.email ?? 'Signed in', email: u.email ?? null, photo: u.photoURL ?? null } : null);
function setUser(u) { user = plain(u); for (const fn of listeners) { try { fn(user); } catch (e) { console.warn('account listener failed', e); } } }

const MESSAGES = {
  'auth/popup-closed-by-user': 'Sign-in was cancelled',
  'auth/cancelled-popup-request': 'Sign-in was cancelled',
  'auth/user-cancelled': 'Sign-in was cancelled',
  'auth/network-request-failed': 'Sign-in needs a connection. Try again when you are online',
  'auth/unauthorized-domain': 'Sign-in is not allowed on this address yet',
  'auth/operation-not-allowed': 'Google sign-in is not turned on yet',
  'auth/too-many-requests': 'Too many sign-in attempts. Try again in a few minutes',
  'auth/user-disabled': 'This account is disabled',
};
function readable(e) {
  const err = new Error(MESSAGES[e?.code] ?? 'Sign-in did not work. Try again');
  err.code = e?.code ?? null; err.cause = e;
  return err;
}

export function initAccount(config) {
  initP ??= (async () => {
    state = 'loading';
    try {
      const [appMod, authMod] = await Promise.all([import(`${SDK}firebase-app.js`), import(`${SDK}firebase-auth.js`)]);
      fb = authMod;
      const app = appMod.getApps().find((a) => a.name === 'cyclescape') ?? appMod.initializeApp(config, 'cyclescape');
      auth = authMod.getAuth(app);
      // the first state comes from the stored session (IndexedDB); a returning redirect sign-in lands here too
      await new Promise((resolve) => {
        let first = true;
        authMod.onAuthStateChanged(auth, (u) => { setUser(u); if (first) { first = false; resolve(); } }, () => { if (first) { first = false; resolve(); } });
        setTimeout(resolve, 10000); // never hang the caller on a stuck session restore
      });
      try { await authMod.getRedirectResult(auth); } catch (e) { lastError = readable(e); }
      state = 'ready';
    } catch (e) {
      console.warn('sign-in is not available', e);
      state = 'failed'; initP = null; // a later call may try again (offline at first)
      setUser(null); // listeners learn that sign-in is not available (accountState() says 'failed')
      throw readable(e);
    }
  })();
  return initP;
}

export function onUser(fn) { listeners.add(fn); try { fn(user); } catch (e) { console.warn('account listener failed', e); } return () => listeners.delete(fn); }
export const currentUser = () => user;
// 'idle' (not started) | 'loading' | 'ready' | 'failed': lets the UI say "Checking sign-in…"
export const accountState = () => state;
// an error a redirect sign-in came back with (shown once by the routes page), then cleared
export function takeAccountError() { const e = lastError; lastError = null; return e; }

export async function signIn() {
  if (!auth) {
    if (!initP) throw Object.assign(new Error('Sign-in is not available right now'), { code: 'cyclescape/not-ready' });
    await initP;
  }
  const provider = new fb.GoogleAuthProvider();
  provider.setCustomParameters({ prompt: 'select_account' });
  try {
    await fb.signInWithPopup(auth, provider);
  } catch (e) {
    if (e?.code === 'auth/popup-blocked' || e?.code === 'auth/operation-not-supported-in-this-environment') {
      try { await fb.signInWithRedirect(auth, provider); return; } catch (e2) { throw readable(e2); } // the page leaves for Google
    }
    throw readable(e);
  }
}

export async function signOut() {
  if (!auth) return;
  try { await fb.signOut(auth); } catch (e) { throw readable(e); }
}

export async function idToken() {
  try { return auth?.currentUser ? await fb.getIdToken(auth.currentUser) : null; } catch (e) { console.warn('could not get the sign-in token', e); return null; }
}
