// The route's start and end flags as map markers (inline SVG, no image files).
//   start: a white flag on a green map pin, after "Flag" by Johan H. W. Basberg (The Noun Project 12703, public domain)
//   end:   a checkered flag on its pole, the cloth's background white so the checks read on any basemap, after
//          "Checkered flag" by Road Signs (The Noun Project 13118, public domain)
// Each marker's anchor is where the flag stands: the pin's tip, the pole's foot (MapLibre Marker anchor + offset).

const START_SVG = `<svg viewBox="0 0 40 50" width="40" height="50" aria-hidden="true">
  <defs><linearGradient id="fl-g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#34d26c"/><stop offset="1" stop-color="#11893a"/></linearGradient></defs>
  <ellipse cx="20" cy="47.5" rx="6.5" ry="2" fill="#000" opacity=".35"/>
  <path d="M20 47 L11.6 32.6 A16.5 16.5 0 1 1 28.4 32.6 Z" fill="url(#fl-g)" stroke="#fff" stroke-width="2.4" stroke-linejoin="round"/>
  <path d="M20 47 L11.6 32.6 A16.5 16.5 0 1 1 28.4 32.6 Z" fill="none" stroke="#0b3d1e" stroke-opacity=".55" stroke-width=".8" stroke-linejoin="round"/>
  <line x1="14" y1="9.5" x2="14" y2="29" stroke="#fff" stroke-width="2.6" stroke-linecap="round"/>
  <path d="M15.2 10.2 C18.8 8.2 22 12.4 27.6 10.2 L27.6 20.4 C22 22.6 18.8 18.4 15.2 20.4 Z" fill="#fff"/>
</svg>`;

// the checks: 4 columns x 3 rows over the cloth, clipped to its waving outline
const checks = () => { let s = ''; for (let r = 0; r < 3; r++) for (let c = 0; c < 4; c++) if ((r + c) % 2 === 0) s += `<rect x="${6 + 7 * c}" y="${1 + 7 * r}" width="7" height="7"/>`; return s; };
const CLOTH = 'M6 5.5 C13 1.5 20 9.5 27 5.5 C30 3.8 32 3.8 34 4.8 L34 21 C32 20 30 20 27 21.6 C20 25.6 13 17.6 6 21.6 Z';
const END_SVG = `<svg viewBox="0 0 36 46" width="36" height="46" aria-hidden="true">
  <defs><clipPath id="fl-c"><path d="${CLOTH}"/></clipPath></defs>
  <ellipse cx="5.5" cy="43.8" rx="4.5" ry="1.6" fill="#000" opacity=".35"/>
  <line x1="5" y1="2.5" x2="5" y2="43" stroke="#fff" stroke-width="5" stroke-linecap="round"/>
  <path d="${CLOTH}" fill="#fff" stroke="#fff" stroke-width="3.2" stroke-linejoin="round"/>
  <g clip-path="url(#fl-c)" fill="#111">${checks()}</g>
  <path d="${CLOTH}" fill="none" stroke="#111" stroke-width="1.4" stroke-linejoin="round"/>
  <line x1="5" y1="2.5" x2="5" y2="43" stroke="#111" stroke-width="2.6" stroke-linecap="round"/>
</svg>`;

function el(cls, svg, title) {
  const d = document.createElement('div');
  d.className = `flag ${cls}`; d.innerHTML = svg; d.title = title; d.setAttribute('role', 'button'); d.setAttribute('aria-label', title);
  return d;
}
// { element, anchor, offset } for new maplibregl.Marker(...)
export const startFlag = (title = 'Start') => ({ element: el('flag-start', START_SVG, title), anchor: 'bottom', offset: [0, 2] });
export const endFlag = (title = 'End') => ({ element: el('flag-end', END_SVG, title), anchor: 'bottom-left', offset: [-5, 3] });
