    for (let j = 0; j < nc; j++, ci++) {
      T.coordX[ci] = (j === 0 ? T.nodeX[A] : j === nc - 1 ? T.nodeX[B] : T.coordX[ci - 1]) + rX.s();
      T.coordY[ci] = (j === 0 ? T.nodeY[A] : j === nc - 1 ? T.nodeY[B] : T.coordY[ci - 1]) + rY.s();
    }
