// The Routes & account page (plan §1b): a full-page panel over the map with
//   - Account: Sign in with Google / who is signed in, Sign out (account.mjs)
//   - Save current route: online when signed in (cloud.mjs), or in this browser (saved.mjs)
//   - Online (signed in): the user's routes on the server: open, rename, delete, GPX, share / stop sharing
//   - This browser: the routes kept in IndexedDB: open, rename, delete, GPX, upload (signed in)
// The app hands it a host:
//   host = { current(): { meta, data } | null,          the route on screen as a saveable record (null: none)
//            open(record, { source: 'local'|'online'|'share', id }),   put a record on the map (the page closes)
//            exportGpx(record),                          download a record as GPX
//            saved,                                      the saved.mjs module
//            tx(english, vars), lang() }                 strings (i18n.mjs t) and the language ('en' | 'ja')
// initRoutesPage(host) -> { open(), close(), isOpen(), setOpened(src | null) }
//   setOpened({ source, id, name }): the route on screen came from that record (the page then offers "Save changes");
//   null when the route on screen is new (cleared, drawn afresh). open() of a row sets it by itself.
// The page renders its own DOM into document.body and injects its CSS once (#routes-page-css).
import { onUser, currentUser, accountState, takeAccountError, signIn, signOut } from './account.mjs';
import * as cloud from './cloud.mjs';

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

