let cssDone = false;
function injectCss() {
  if (cssDone || document.getElementById('routes-page-css')) { cssDone = true; return; }
  const s = document.createElement('style'); s.id = 'routes-page-css'; s.textContent = STYLE; document.head.append(s); cssDone = true;
}

export function initRoutesPage(host) {
  injectCss();
  const T = (s, v) => host.tx(s, v);
  const root = document.createElement('div');
  root.id = 'routes-page'; root.hidden = true;
  root.setAttribute('role', 'dialog'); root.setAttribute('aria-modal', 'true'); root.setAttribute('aria-labelledby', 'rp-title');
  document.body.append(root);

  const st = {
    user: currentUser(), signing: false, accountErr: null,
    online: { status: 'idle', routes: [], next: null, error: null, more: false },
    sort: { by: 'date', dir: -1 },
    edit: null,      // { list: 'online'|'local', id, kind: 'rename'|'delete' }
    busy: new Set(), // `${list}:${id}` rows working
    rowMsg: new Map(), // `${list}:${id}` -> { text, bad }
    link: null,      // { id, url } the share link shown under an online row
    save: { name: '', msg: null, bad: false, busy: false },
    opened: null,    // { source, id, name } the route on screen came from
  };
  let lastFocus = null;

  const fmtDate = (d) => {
    if (d == null) return '';
    const t = typeof d === 'number' ? new Date(d) : new Date(d?._seconds != null ? d._seconds * 1000 : d);
    if (Number.isNaN(+t)) return '';
    return t.toLocaleDateString(host.lang() === 'ja' ? 'ja-JP' : 'en-GB', { year: 'numeric', month: 'short', day: 'numeric' });
  };
  const metaLine = (m) => {
    const parts = [];
    if (m.lengthM != null) parts.push(T('{km} km', { km: (m.lengthM / 1000).toFixed(m.lengthM < 10000 ? 1 : 0) }));
    if (m.gainM != null) parts.push(T('↑{m} m', { m: Math.round(m.gainM) }));
    const n = Array.isArray(m.points) ? m.points.length : typeof m.points === 'number' ? m.points : null;
    if (n) parts.push(T('{n} points', { n }));
    const d = fmtDate(m.updated ?? m.created); if (d) parts.push(d);
    return parts.join(' · ');
  };
  const defaultName = () => {
    const c = host.current(); const n = c?.meta?.name;
    if (n) return n;
    return `${T('Route')} ${new Date().toLocaleDateString(host.lang() === 'ja' ? 'ja-JP' : 'en-GB', { year: 'numeric', month: 'short', day: 'numeric' })}`;
  };
  const key = (list, id) => `${list}:${id}`;
  const signedIn = () => !!st.user;

  // ---- rendering ----
  function accountHtml() {
    const s = accountState();
    let body;
    if (st.user) {
      const u = st.user, initial = esc((u.name ?? '?').trim().charAt(0).toUpperCase() || '?');
      body = `<div class="rp-who">${u.photo ? `<img src="${esc(u.photo)}" alt="" referrerpolicy="no-referrer">` : `<span class="rp-av">${initial}</span>`}` +
        `<div class="rp-id"><b>${esc(u.name)}</b>${u.email ? `<small>${esc(u.email)}</small>` : ''}</div>` +
        `<button data-act="signout">${esc(T('Sign out'))}</button></div>`;
    } else if (s === 'loading' || s === 'idle' && st.signing) {
      body = `<div class="rp-hint" style="margin:0">${esc(T('Checking sign-in…'))}</div>`;
    } else if (s === 'failed' || s === 'idle') {
      body = `<div class="rp-hint" style="margin:0">${esc(T('Sign-in is not available right now.'))}</div>`;
    } else {
      body = `<button class="rp-google" data-act="signin"${st.signing ? ' disabled' : ''}>${GOOGLE}<span>${esc(T(st.signing ? 'Signing in…' : 'Sign in with Google'))}</span></button>` +
        `<p class="rp-hint">${esc(T('Optional. Signed in, you can keep routes online, open them on any device and send share links.'))}</p>`;
    }
    return `<section><h3>${esc(T('Account'))}</h3><div class="rp-card">${body}${st.accountErr ? `<p class="rp-err">${esc(T(st.accountErr))}</p>` : ''}</div></section>`;
  }
  function saveHtml() {
    const cur = host.current();
    let body;
    if (!cur) body = `<div class="rp-hint" style="margin:0">${esc(T('Draw a route on the map to save it.'))}</div>`;
    else {
      const o = st.opened, b = st.save.busy ? ' disabled' : '';
      const over = o && ((o.source === 'online' && signedIn()) || o.source === 'local')
        ? `<button class="primary" data-act="save-over"${b}>${esc(T('Save changes to “{name}”', { name: o.name ?? T('Route') }))}</button>` : '';
      body = `<input class="rp-name" id="rp-save-name" type="text" autocomplete="off" maxlength="120" aria-label="${esc(T('Route name'))}" placeholder="${esc(T('Route name'))}" value="${esc(st.save.name)}">` +
        `<div class="rp-row">${over}` +
        (signedIn() ? `<button class="${over ? '' : 'primary'}" data-act="save-online"${b}>${esc(T('Save online'))}</button>` : '') +
        `<button class="${over || signedIn() ? '' : 'primary'}" data-act="save-local"${b}>${esc(T('Save in this browser'))}</button></div>` +
        (signedIn() ? '' : `<p class="rp-hint">${esc(T('Sign in to save routes online and share them.'))}</p>`);
    }
    const m = st.save.busy ? { text: 'Saving…', bad: false } : st.save.msg ? { text: st.save.msg, bad: st.save.bad } : null;
    return `<section><h3>${esc(T('Save current route'))}</h3><div class="rp-card">${body}${m ? `<p class="${m.bad ? 'rp-err' : 'rp-ok'}" role="status">${esc(T(m.text))}</p>` : ''}</div></section>`;
  }
  function editHtml(list, m) {
    const e = st.edit;
    if (!e || e.list !== list || e.id !== m.id) return '';
    if (e.kind === 'rename') {
      return `<div class="rp-edit"><input class="rp-name" data-rename="1" type="text" autocomplete="off" maxlength="120" aria-label="${esc(T('Route name'))}" value="${esc(e.value ?? m.name ?? '')}">` +
        `<button class="primary" data-act="rename-ok">${esc(T('Save'))}</button><button data-act="edit-cancel">${esc(T('Cancel'))}</button></div>`;
    }
    return `<div class="rp-edit"><p class="rp-err">${esc(T('Delete “{name}”? This cannot be undone.', { name: m.name ?? T('Route') }))}</p>` +
      `<button class="danger" data-act="delete-ok">${esc(T('Delete'))}</button><button data-act="edit-cancel">${esc(T('Cancel'))}</button></div>`;
  }
  function itemHtml(list, m) {
    const k = key(list, m.id), busy = st.busy.has(k) ? ' disabled' : '', msg = st.rowMsg.get(k);
    const on = st.opened && st.opened.source === list && st.opened.id === m.id;
    const acts = [
      `<button class="go" data-act="open"${busy}>${esc(T('Open'))}</button>`,
      `<button data-act="rename"${busy}>${esc(T('Rename'))}</button>`,
      `<button data-act="gpx"${busy}>${esc(T('GPX'))}</button>`,
    ];
    if (list === 'online') acts.push(m.shareId ? `<button data-act="share"${busy}>${esc(T('Share link'))}</button><button data-act="unshare"${busy}>${esc(T('Stop sharing'))}</button>` : `<button data-act="share"${busy}>${esc(T('Share'))}</button>`);
    if (list === 'local' && signedIn()) acts.push(`<button data-act="upload"${busy}>${esc(T('Upload'))}</button>`);
    acts.push(`<button class="danger" data-act="delete"${busy}>${esc(T('Delete'))}</button>`);
    const link = list === 'online' && st.link?.id === m.id
      ? `<div class="rp-link"><input type="text" readonly value="${esc(st.link.url)}" aria-label="${esc(T('Share link'))}"><button data-act="copy">${esc(T(st.link.copied ? 'Copied' : 'Copy'))}</button></div><p class="rp-hint">${esc(T('Anyone with this link can see the route.'))}</p>` : '';
    return `<div class="rp-item${on ? ' on' : ''}" data-list="${list}" data-id="${esc(m.id)}"><div class="rp-top"><span class="rp-title">${esc(m.name || T('Route'))}</span>` +
      (list === 'online' && m.shareId ? `<span class="rp-badge">${esc(T('Shared'))}</span>` : '') + '</div>' +
      `<div class="rp-meta">${esc(metaLine(m))}</div><div class="rp-acts">${acts.join('')}</div>${editHtml(list, m)}${link}` +
      (msg ? `<p class="${msg.bad ? 'rp-err' : 'rp-ok'}" role="status">${esc(T(msg.text))}</p>` : '') + '</div>';
  }
  function onlineHtml() {
    if (!signedIn()) return '';
    const o = st.online;
    let body;
    if (o.status === 'loading' && !o.routes.length) body = `<div class="rp-none">${esc(T('Loading…'))}</div>`;
    else if (o.status === 'error' && !o.routes.length) body = `<div class="rp-card"><div class="rp-err" style="margin:0">${esc(T(o.error ?? 'Online routes are not reachable right now'))}</div><div class="rp-row" style="margin-top:8px"><button data-act="reload">${esc(T('Try again'))}</button></div></div>`;
    else if (!o.routes.length) body = `<div class="rp-none">${esc(T('No routes saved online yet.'))}</div>`;
    else {
      body = `<div class="rp-list">${o.routes.map((m) => itemHtml('online', m)).join('')}</div>` +
        (o.status === 'error' ? `<p class="rp-err">${esc(T(o.error ?? 'Online routes are not reachable right now'))}</p>` : '') +
        (o.next ? `<button class="rp-more" data-act="more"${o.more ? ' disabled' : ''}>${esc(T(o.more ? 'Loading…' : 'Show more'))}</button>` : '');
    }
    return `<section><h3>${esc(T('Online'))}${o.routes.length ? ` <span class="n">${o.routes.length}${o.next ? '+' : ''}</span>` : ''}</h3>${body}</section>`;
  }
  function localHtml() {
    const list = host.saved.sortSaved(host.saved.listSaved(), st.sort.by, st.sort.dir);
    const sortBtn = (by, label) => `<button data-act="sort" data-by="${by}" aria-pressed="${st.sort.by === by}" class="${st.sort.by === by ? 'on' : ''}">${esc(T(label))}${st.sort.by === by ? (st.sort.dir > 0 ? ' ↑' : ' ↓') : ''}</button>`;
    const body = list.length ? `<div class="rp-list">${list.map((m) => itemHtml('local', m)).join('')}</div>` : `<div class="rp-none">${esc(T('No routes saved in this browser yet.'))}</div>`;
    return `<section><h3>${esc(T('This browser'))}${list.length ? ` <span class="n">${list.length}</span>` : ''}` +
      (list.length > 1 ? `<span class="rp-sort">${sortBtn('date', 'Date')}${sortBtn('name', 'Name')}</span>` : '') + `</h3>${body}` +
      `<p class="rp-hint">${esc(T('Saved in this browser only (for this address).'))}</p></section>`;
  }
  function render() {
    if (root.hidden) return;
    // keep what is being typed and where the cursor is across a re-render
    const a = document.activeElement, focusSel = a && root.contains(a) ? selectorOf(a) : null;
    const nameEl = root.querySelector('#rp-save-name'); if (nameEl) st.save.name = nameEl.value;
    const ren = root.querySelector('[data-rename]'); if (ren && st.edit) st.edit.value = ren.value;
    const scroll = root.querySelector('.rp-body')?.scrollTop ?? 0;
    root.innerHTML = `<div class="rp-head"><h2 id="rp-title">${esc(T('Routes & account'))}</h2><button class="rp-close" data-act="close" title="${esc(T('Close'))}" aria-label="${esc(T('Close'))}">✕</button></div>` +
      `<div class="rp-body"><div class="rp-col">${accountHtml()}${saveHtml()}${onlineHtml()}${localHtml()}</div></div>`;
    root.querySelector('.rp-body').scrollTop = scroll;
    const want = root.querySelector('[data-rename]') && st.edit?.focus ? root.querySelector('[data-rename]') : focusSel ? root.querySelector(focusSel) : null;
    if (want) { want.focus({ preventScroll: true }); if (st.edit?.focus) { want.select?.(); st.edit.focus = false; } }
  }
  function selectorOf(el) {
    if (el.id) return `#${CSS.escape(el.id)}`;
    if (el.dataset.rename) return '[data-rename]';
    const item = el.closest('.rp-item'), act = el.dataset.act;
    if (item && act) return `.rp-item[data-list="${item.dataset.list}"][data-id="${CSS.escape(item.dataset.id)}"] [data-act="${act}"]`;
    if (act) return `[data-act="${act}"]`;
    return null;
  }

  // ---- data ----
  let listSeq = 0;
  async function loadOnline(more = false) {
    if (!signedIn()) return;
    const o = st.online, seq = ++listSeq;
    if (more) o.more = true; else { o.status = 'loading'; o.error = null; }
    render();
    const r = await cloud.listRoutes(more ? o.next : undefined);
    if (seq !== listSeq) return;
    o.more = false;
    if (r.error) { o.status = 'error'; o.error = r.error; render(); return; }
    o.routes = more ? [...o.routes, ...r.routes.filter((m) => !o.routes.some((x) => x.id === m.id))] : r.routes;
    o.next = r.next; o.status = 'ready'; render();
  }
  const metaOf = (list, id) => (list === 'online' ? st.online.routes.find((m) => m.id === id) : host.saved.getSaved?.(id) ?? host.saved.listSaved().find((m) => m.id === id)) ?? null;
  async function recordOf(list, id) {
    if (list === 'online') { const r = await cloud.getRoute(id); return r.error ? r : { meta: r.meta ?? metaOf(list, id), data: r.data }; }
    const data = await host.saved.loadRoute(id); if (!data) return { error: 'Could not open this route.' };
    const { id: _drop, ...rest } = data; // the local store keeps the id inside its data record
    return { meta: metaOf(list, id), data: rest };
  }
  // the parts of a list entry that describe the route (not where or when it was kept)
  const cleanMeta = (m) => { const { id, created, updated, bytes, shareId, ...rest } = m ?? {}; return rest; };
  const rowMsg = (list, id, text, bad = false) => { st.rowMsg.set(key(list, id), { text, bad }); };
  async function rowWork(list, id, fn) {
    const k = key(list, id); if (st.busy.has(k)) return;
    st.busy.add(k); st.rowMsg.delete(k); render();
    try { await fn(); } finally { st.busy.delete(k); render(); }
  }

  async function act(name, list, id, btn) {
    const m = id != null ? metaOf(list, id) : null;
    switch (name) {
      case 'close': close(); return;
      case 'signin': {
        st.signing = true; st.accountErr = null; render();
        try { await signIn(); } catch (e) { st.accountErr = e?.message ?? 'Sign-in did not work. Try again'; }
        st.signing = false; render(); return;
      }
      case 'signout': try { await signOut(); } catch (e) { st.accountErr = e?.message ?? null; render(); } return;
      case 'reload': loadOnline(); return;
      case 'more': loadOnline(true); return;
      case 'sort': {
        const by = btn.dataset.by;
        st.sort = st.sort.by === by ? { by, dir: -st.sort.dir } : { by, dir: by === 'name' ? 1 : -1 };
        render(); return;
      }
      case 'save-online': case 'save-local': case 'save-over': await save(name); return;
      case 'open': {
        await rowWork(list, id, async () => {
          rowMsg(list, id, 'Opening…'); render();
          const rec = await recordOf(list, id);
          if (rec.error || !rec.data) { rowMsg(list, id, rec.error ?? 'Could not open this route.', true); return; }
          st.rowMsg.delete(key(list, id));
          st.opened = { source: list, id, name: rec.meta?.name ?? m?.name ?? null };
          host.open(rec, { source: list, id });
          close();
        });
        return;
      }
      case 'gpx': {
        await rowWork(list, id, async () => {
          const rec = await recordOf(list, id);
          if (rec.error || !rec.data) { rowMsg(list, id, rec.error ?? 'Could not open this route.', true); return; }
          host.exportGpx(rec);
        });
        return;
      }
      case 'rename': st.edit = { list, id, kind: 'rename', value: m?.name ?? '', focus: true }; render(); return;
      case 'delete': st.edit = { list, id, kind: 'delete' }; render(); root.querySelector('[data-act="delete-ok"]')?.focus(); return;
      case 'edit-cancel': st.edit = null; render(); return;
      case 'rename-ok': {
        const e = st.edit; if (!e) return;
        const name = (root.querySelector('[data-rename]')?.value ?? '').trim().slice(0, 120); if (!name) return;
        st.edit = null;
        await rowWork(e.list, e.id, async () => {
          if (e.list === 'online') {
            const r = await cloud.renameRoute(e.id, name);
            if (r.error) { rowMsg(e.list, e.id, r.error, true); return; }
            const x = st.online.routes.find((q) => q.id === e.id); if (x) x.name = name;
          } else if (!(await host.saved.renameSaved(e.id, name))) { rowMsg(e.list, e.id, 'Could not save in this browser (storage is off or full).', true); return; }
          if (st.opened?.source === e.list && st.opened.id === e.id) st.opened.name = name;
        });
        return;
      }
      case 'delete-ok': {
        const e = st.edit; if (!e) return; st.edit = null;
        await rowWork(e.list, e.id, async () => {
          if (e.list === 'online') {
            const r = await cloud.deleteRoute(e.id);
            if (r.error && r.status !== 404) { rowMsg(e.list, e.id, r.error, true); return; }
            st.online.routes = st.online.routes.filter((q) => q.id !== e.id);
            if (st.link?.id === e.id) st.link = null;
          } else if (!(await host.saved.removeSaved(e.id))) { rowMsg(e.list, e.id, 'Could not save in this browser (storage is off or full).', true); return; }
          if (st.opened?.source === e.list && st.opened.id === e.id) st.opened = null;
        });
        return;
      }
      case 'upload': {
        await rowWork(list, id, async () => {
          const rec = await recordOf(list, id);
          if (rec.error || !rec.data) { rowMsg(list, id, rec.error ?? 'Could not open this route.', true); return; }
          const r = await cloud.createRoute(cleanMeta(rec.meta), rec.data);
          if (r.error) { rowMsg(list, id, r.error, true); return; }
          rowMsg(list, id, 'Uploaded');
          loadOnline();
        });
        return;
      }
      case 'share': {
        await rowWork(list, id, async () => {
          let sid = m?.shareId;
          if (!sid) {
            const r = await cloud.shareRoute(id);
            if (r.error) { rowMsg(list, id, r.error, true); return; }
            sid = r.shareId; if (m) m.shareId = sid;
          }
          const url = cloud.shareUrl(sid);
          st.link = { id, url, copied: false };
          if (navigator.share && matchMedia?.('(pointer: coarse)').matches) {
            try { await navigator.share({ title: m?.name ?? 'CycleScape', url }); } catch { /* dismissed: the link stays shown */ }
          }
        });
        return;
      }
      case 'unshare': {
        await rowWork(list, id, async () => {
          const r = await cloud.unshareRoute(id);
          if (r.error) { rowMsg(list, id, r.error, true); return; }
          if (m) m.shareId = null; if (st.link?.id === id) st.link = null;
          rowMsg(list, id, 'Sharing stopped');
        });
        return;
      }
      case 'copy': {
        const inp = btn.closest('.rp-link')?.querySelector('input'); if (!inp || !st.link) return;
        let ok = false;
        try { await navigator.clipboard.writeText(st.link.url); ok = true; } catch { inp.select(); try { ok = document.execCommand('copy'); } catch { ok = false; } }
        if (ok) { st.link.copied = true; render(); }
        return;
      }
      default:
    }
  }

  async function save(kind) {
    const cur = host.current(); if (!cur) return;
    const name = ((root.querySelector('#rp-save-name')?.value ?? st.save.name).trim() || defaultName()).slice(0, 120);
    st.save = { ...st.save, name, busy: true, msg: null, bad: false }; render();
    const meta = { ...cleanMeta(cur.meta), name }, o = st.opened;
    let msg = null, bad = false;
    try {
      if (kind === 'save-online' || (kind === 'save-over' && o?.source === 'online')) {
        const r = kind === 'save-over' ? await cloud.putRoute(o.id, meta, cur.data) : await cloud.createRoute(meta, cur.data);
        if (r.error) { msg = r.error; bad = true; } else {
          msg = 'Saved online';
          st.opened = { source: 'online', id: kind === 'save-over' ? o.id : r.id, name };
          loadOnline();
        }
      } else {
        const r = await host.saved.saveRoute(kind === 'save-over' && o?.source === 'local' ? { ...meta, id: o.id } : meta, cur.data);
        if (!r) { msg = 'Could not save in this browser (storage is off or full).'; bad = true; } else { msg = 'Saved in this browser'; st.opened = { source: 'local', id: r.id, name }; }
      }
    } finally { st.save = { ...st.save, busy: false, msg, bad }; render(); }
  }

  // ---- events ----
  root.addEventListener('click', (e) => {
    const b = e.target.closest('button[data-act]'); if (!b || b.disabled) return;
    const item = b.closest('.rp-item');
    act(b.dataset.act, item?.dataset.list ?? null, item?.dataset.id ?? null, b);
  });
  root.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      e.preventDefault(); e.stopPropagation(); // the app's own Esc (clear the route) must not run behind the page
      if (st.edit) { st.edit = null; render(); } else close();
      return;
    }
    if (e.key === 'Enter') {
      if (e.target.matches('[data-rename]')) { e.preventDefault(); act('rename-ok'); }
      else if (e.target.id === 'rp-save-name') { e.preventDefault(); act(signedIn() ? 'save-online' : 'save-local'); }
      return;
    }
    if (e.key === 'Tab') { // keep the keyboard inside the page
      const f = [...root.querySelectorAll('button:not([disabled]), input, [tabindex]:not([tabindex="-1"])')].filter((x) => x.offsetParent !== null);
      if (!f.length) return;
      const first = f[0], last = f.at(-1);
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
    e.stopPropagation(); // typing in the page is not the map's shortcuts (Backspace = undo)
  });
  root.addEventListener('input', (e) => { if (e.target.id === 'rp-save-name') st.save.name = e.target.value; });

  onUser((u) => {
    const was = st.user?.uid ?? null;
    st.user = u;
    if ((u?.uid ?? null) !== was) {
      st.online = { status: 'idle', routes: [], next: null, error: null, more: false }; st.link = null;
      if (st.opened?.source === 'online') st.opened = null;
      if (u && !root.hidden) loadOnline();
    }
    render();
  });

  function open() {
    if (!root.hidden) return;
    lastFocus = document.activeElement;
    const err = takeAccountError(); if (err) st.accountErr = err.message;
    st.save = { name: defaultName(), msg: null, bad: false, busy: false }; st.edit = null; st.rowMsg.clear(); st.link = null;
    root.hidden = false; document.body.classList.add('routes-page-open');
    render();
    if (signedIn()) loadOnline();
    root.querySelector('.rp-close')?.focus();
  }
  function close() {
    if (root.hidden) return;
    root.hidden = true; document.body.classList.remove('routes-page-open'); st.edit = null;
    if (lastFocus?.isConnected) lastFocus.focus?.({ preventScroll: true });
  }
  return {
    open, close, isOpen: () => !root.hidden,
    setOpened(src) { st.opened = src ? { source: src.source, id: src.id, name: src.name ?? null } : null; render(); },
  };
}
