// Online routes: the client of the CycleScape API (Cloud Run "cyclescape-api", plan §1a; CONTRACT §8).
// Every call returns its value, or { error, status? } on failure (no throw), like saved.mjs reports null.
// Calls for the signed-in user send the Firebase ID token (account.mjs idToken) as a Bearer token; without a token
// they answer { error, status: 401 } at once, without a request. getShared() is public and sends none.
//   route metadata (meta): { id, name, created, updated, lengthM, gainM, lossM, points, segs, ended, bytes, shareId }
//   a route record:        { meta, data }   data: the planner's saved record (plan.mjs encodeRecord), any JSON
import { idToken } from './account.mjs';

let api = '', tokenSource = idToken, timeoutMs = 15000;
const UPLOAD_MS = 60000; // a long route's body takes longer than a list on a slow phone connection
export const setApi = (url) => { api = String(url ?? '').replace(/\/+$/, ''); };
export const setTokenSource = (fn) => { tokenSource = fn; }; // tests
export const setTimeoutMs = (ms) => { timeoutMs = ms; }; // tests

const MSG = {
  offline: 'Online routes are not reachable right now',
  timeout: 'Online routes took too long to answer',
  signin: 'Sign in to use online routes',
  notFound: 'This route is not there any more',
  setup: 'Online routes are not set up',
  server: 'Something went wrong online. Try again later',
  tooBig: 'This route is too large to keep online',
};
const fail = (error, status) => (status != null ? { error, status } : { error });

async function call(method, path, { body, auth = true, ms } = {}) {
  if (!api) return fail(MSG.setup);
  const headers = {};
  if (auth) {
    let t = null;
    try { t = await tokenSource?.(); } catch { t = null; }
    if (!t) return fail(MSG.signin, 401);
    headers.Authorization = `Bearer ${t}`;
  }
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  const ctl = new AbortController(), timer = setTimeout(() => ctl.abort(), ms ?? timeoutMs);
  let res;
  try {
    res = await fetch(api + path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body), signal: ctl.signal });
  } catch (e) {
    clearTimeout(timer);
    return fail(ctl.signal.aborted ? MSG.timeout : MSG.offline);
  }
  let json = null;
  try { const text = await res.text(); json = text ? JSON.parse(text) : null; } catch { json = null; }
  clearTimeout(timer);
  if (!res.ok) {
    const s = res.status;
    const msg = s === 401 ? MSG.signin : s === 404 ? MSG.notFound : s === 413 ? MSG.tooBig
      : s >= 500 ? MSG.server : (typeof json?.error === 'string' && json.error) || MSG.server;
    return fail(msg, s);
  }
  return json ?? { ok: true };
}
const enc = encodeURIComponent;

// the user's routes, newest first, 50 a page: { routes: [meta], next: cursor | null }
export async function listRoutes(after) {
  const r = await call('GET', `/api/routes${after ? `?after=${enc(after)}` : ''}`);
  if (r.error) return r;
  return { routes: Array.isArray(r.routes) ? r.routes : [], next: r.next ?? null };
}
export const createRoute = (meta, data) => call('POST', '/api/routes', { body: { meta, data }, ms: UPLOAD_MS }); // { id }
export const getRoute = (id) => call('GET', `/api/routes/${enc(id)}`); // { meta, data }
export const putRoute = (id, meta, data) => call('PUT', `/api/routes/${enc(id)}`, { body: { meta, data }, ms: UPLOAD_MS });
export const renameRoute = (id, name) => call('PATCH', `/api/routes/${enc(id)}`, { body: { name } });
export const deleteRoute = (id) => call('DELETE', `/api/routes/${enc(id)}`);
export const shareRoute = (id) => call('POST', `/api/routes/${enc(id)}/share`); // { shareId }
export const unshareRoute = (id) => call('DELETE', `/api/routes/${enc(id)}/share`);
export const getShared = (shareId) => call('GET', `/api/share/${enc(shareId)}`, { auth: false }); // { meta, data }

// the link someone else opens: the published app, or this page when it runs on localhost
export function shareUrl(shareId) {
  const loc = globalThis.location;
  if (loc && /^(localhost|127\.0\.0\.1|\[::1\])$/.test(loc.hostname)) return `${loc.origin}${loc.pathname}#share=${shareId}`;
  return `https://max-mapper.github.io/cyclescape/#share=${shareId}`;
}
