// GSI 淡色+陰影 basemap: GSI's own style (snapshot: scripts/snapshot-gsi-pale.mjs -> styles/gsi-pale-hillshade.json)
// plus the two things MapLibre can't take from GSI directly:
//   gsidem://z/x/y   GSI's DEM PNG tiles (dem_png, DEM10B to z14) re-encoded as Terrarium for the hillshade layer.
//                    GSI packs height as (R·65536 + G·256 + B)·0.01 m, two's complement over 24 bits, 0x800000 = no
//                    data (sea); no data and missing tiles become 0 m (flat, so no shading over the sea).
//   icons            GSI's 'pale' sprite sheet has no @2x variant, so it is cut up here and added with addImage.
//   hatches          fill patterns GSI's code draws at run time ('-gsibv-hatch-<type>-<size>-<r,g,b,a>-<bg r,g,b,a>'),
//                    drawn here the same way (GSIBV.Map.HatchImageManager.drawHatch).
const DEM = 'https://cyberjapandata.gsi.go.jp/xyz/dem_png/';
const STYLE_URL = new URL('styles/gsi-pale-hillshade.json', document.baseURI).href; // web/styles in dev, build/styles when built

let flat = null;
async function png(rgba) {
  const c = new OffscreenCanvas(256, 256), ctx = c.getContext('2d');
  ctx.putImageData(new ImageData(rgba, 256, 256), 0, 0);
  return (await c.convertToBlob({ type: 'image/png' })).arrayBuffer();
}
const terrarium = (h, px, i) => { const v = h + 32768; px[i] = Math.floor(v / 256); px[i + 1] = Math.floor(v) % 256; px[i + 2] = Math.floor((v - Math.floor(v)) * 256); px[i + 3] = 255; };
export async function gsiDemTile(z, x, y, signal) {
  const res = await fetch(`${DEM}${z}/${x}/${y}.png`, { signal });
  if (!res.ok) { // outside GSI's coverage (open sea): flat
    if (!flat) { const px = new Uint8ClampedArray(256 * 256 * 4); for (let i = 0; i < px.length; i += 4) terrarium(0, px, i); flat = png(px); }
    return (await flat).slice(0);
  }
  const bmp = await createImageBitmap(await res.blob(), { colorSpaceConversion: 'none', premultiplyAlpha: 'none' });
  const c = new OffscreenCanvas(256, 256), ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(bmp, 0, 0); bmp.close();
  const px = ctx.getImageData(0, 0, 256, 256).data;
  for (let i = 0; i < px.length; i += 4) {
    const d = px[i] * 65536 + px[i + 1] * 256 + px[i + 2];
    terrarium(d === 0x800000 ? 0 : (d < 0x800000 ? d : d - 0x1000000) * 0.01, px, i);
  }
  return png(px);
}

let registered = false;
function register() {
  if (registered) return; registered = true;
  maplibregl.addProtocol('gsidem', async (params, abort) => {
    const [z, x, y] = params.url.replace('gsidem://', '').split('/').map(Number);
    // a basemap switch cancels tiles still loading: say so the way MapLibre expects, or it reports each as an error
    try { return { data: await gsiDemTile(z, x, y, abort.signal) }; } catch (e) { throw abort.signal.aborted ? new Error('AbortError') : e; }
  });
}

// the sprite sheet as [name, ImageData-like, pixelRatio]
async function sprite(base) {
  const [index, blob] = await Promise.all([fetch(`${base}.json`).then((r) => r.json()), fetch(`${base}.png`).then((r) => r.blob())]);
  const bmp = await createImageBitmap(blob, { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
  const c = new OffscreenCanvas(bmp.width, bmp.height), ctx = c.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(bmp, 0, 0); bmp.close();
  return Object.entries(index).filter(([, s]) => s.width > 0 && s.height > 0).map(([name, s]) =>
    [name, { width: s.width, height: s.height, data: new Uint8Array(ctx.getImageData(s.x, s.y, s.width, s.height).data.buffer) }, s.pixelRatio || 1]);
}

// '-gsibv-hatch-dot-4-230,230,230,1-' -> { width, height, data }
export function hatch(key) {
  const m = /^-gsibv-hatch-(ltrb|rtlb|cross|plus|minus|dot)-(\d+)-([\d.]+),([\d.]+),([\d.]+),([\d.]+)-(?:([\d.]+),([\d.]+),([\d.]+),([\d.]+))?$/.exec(key);
  if (!m) return null;
  const [type, size] = [m[1], +m[2]], c = m.slice(3, 7).map(Number), bg = m[7] != null ? m.slice(7, 11).map(Number) : null;
  const data = new Uint8Array(size * size * 4);
  if (bg) for (let i = 0; i < data.length; i += 4) data.set([bg[0], bg[1], bg[2], bg[3] * 255], i);
  const dot = (x, y) => data.set([c[0], c[1], c[2], c[3] * 255], (y * size + x) * 4);
  if (type === 'ltrb' || type === 'cross') for (let y = 0; y < size; y++) dot(y, y);
  if (type === 'rtlb' || type === 'cross') for (let y = 0; y < size; y++) dot(size - y - 1, y);
  if (type === 'minus') { for (let x = 1; x < size; x++) dot(x, 3); for (let x = 0; x < size - 1; x++) dot(x, 9); }
  if (type === 'dot') dot(1, 2);
  return { width: size, height: size, data };
}
const patterns = (style) => [...new Set(style.layers.flatMap((l) => [l.paint?.['fill-pattern'], l.paint?.['line-pattern']]).filter((p) => typeof p === 'string' && p.startsWith('-gsibv-hatch-')))];

// STYLES entry: build() loads the style and the icons once; onLoad(map) adds the icons after each setStyle
export function gsiPaleHillshade(title) {
  let icons = [], hatches = [];
  return {
    title,
    build: async () => {
      register();
      const style = await fetch(STYLE_URL).then((r) => { if (!r.ok) throw new Error(`style HTTP ${r.status}`); return r.json(); });
      hatches = patterns(style).map((k) => [k, hatch(k), 1]).filter(([, img]) => img);
      icons = await sprite(style.metadata['cyclescape:sprite']).catch(() => []); // labels still draw without icons
      return style;
    },
    onLoad: (map) => { for (const [name, img, pixelRatio] of [...icons, ...hatches]) if (!map.hasImage(name)) map.addImage(name, img, { pixelRatio }); },
  };
}
